<?php
namespace App\Services;
use Illuminate\Support\Facades\Cache;use Illuminate\Support\Facades\Http;use App\Support\Countries;use libphonenumber\PhoneNumberUtil;
class GeographyService{public function countries():array{return Cache::rememberForever('geography:countries:v1',function(){$phone=PhoneNumberUtil::getInstance();return collect(Countries::getNames('en'))->map(fn($name,$code)=>['code'=>$code,'name'=>$name,'dial_code'=>'+'.$phone->getCountryCodeForRegion($code)])->sortBy('name')->values()->all();});}public function states(string $country):array{return Cache::remember('geography:states:'.strtolower($country),now()->addDays(30),function()use($country){$fallback=config('geography.states.'.$country,[]);try{return Http::connectTimeout(2)->timeout(5)->post('https://countriesnow.space/api/v0.1/countries/states',['country'=>$country])->throw()->collect('data.states')->pluck('name')->filter()->values()->all()?:$fallback;}catch(\Throwable $e){report($e);return $fallback;}});}public function cities(string $country,string $state):array{return Cache::remember('geography:cities:'.md5($country.'|'.$state),now()->addDays(30),function()use($country,$state){$fallback=config('geography.cities.'.$country.'|'.$state,[]);try{return Http::connectTimeout(2)->timeout(5)->post('https://countriesnow.space/api/v0.1/countries/state/cities',compact('country','state'))->throw()->collect('data')->filter()->values()->all()?:$fallback;}catch(\Throwable $e){report($e);return $fallback;}});}}
